<?php if($action==='pages'||$action==='blog'): ?><div class="marketplace-grid"><section class="panel customer-form-panel"><h3><?= $action==='pages'?'Yeni sayfa':'Blog yazısı' ?></h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="<?= $action==='pages'?'page':'blog' ?>"><label>Başlık<input name="title" required></label><label>URL / slug<input name="slug"></label><?php if($action==='blog'): ?><label>Özet<textarea name="excerpt"></textarea></label><?php endif; ?><label>İçerik<textarea name="content" rows="8" required></textarea></label><label>SEO başlığı<input name="meta_title"></label><label>SEO açıklaması<textarea name="meta_description"></textarea></label><label>Durum<select name="status"><option value="draft">Taslak</option><option value="published">Yayında</option></select></label><button class="btn primary">Kaydet</button></form></section><section class="panel customer-list-panel"><h3><?= $action==='pages'?'Sayfalar':'Blog yazıları' ?></h3><?php foreach(($action==='pages'?$pages:$posts) as $p): ?><p><strong><?= kd_e($p['title']) ?></strong><small class="table-sub"><?= kd_e($p['slug']) ?> · <?= kd_e($p['status']) ?></small></p><?php endforeach; ?></section></div>
