<?php elseif($action==='banners'): ?><div class="marketplace-grid"><section class="panel customer-form-panel"><h3>Banner ekle</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="banner"><label>Başlık<input name="title" required></label><label>Alt başlık<input name="subtitle"></label><label>Görsel URL<input type="url" name="image_url"></label><label>Bağlantı URL<input type="url" name="link_url"></label><label>Konum<select name="position"><option value="home_hero">Ana sayfa hero</option><option value="home_strip">Ana sayfa şerit</option></select></label><label>Sıra<input type="number" name="sort_order" value="0"></label><button class="btn primary">Kaydet</button></form></section><section class="panel"><h3>Bannerlar</h3><?php foreach($banners as $b): ?><p><?= kd_e($b['title'].' · '.$b['status']) ?></p><?php endforeach; ?></section></div>
<?php else: ?><section class="panel customer-form-panel"><h3>Mağaza ayarları</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="settings"><?php foreach(['site_name'=>'Site adı','site_tagline'=>'Slogan','site_hero_title'=>'Ana sayfa başlığı','site_hero_subtitle'=>'Ana sayfa açıklaması','site_contact_email'=>'İletişim e-posta','site_phone'=>'Telefon','site_footer_text'=>'Alt bilgi'] as $k=>$label): ?><label><?= kd_e($label) ?><input name="<?= kd_e($k) ?>" value="<?= kd_e($settings[$k]??'') ?>"></label><?php endforeach; ?><button class="btn primary">Ayarları kaydet</button></form><p><a href="store.php" target="_blank">Mağazayı görüntüle</a></p></section><?php endif; ?>
